# Code generated by Claude
"""
Measures the bench rectangle once, offline (decisions-log M150): from the reach maps at the bench pedestal height (TASK_CFG["pedestal_q"]) and the work heights above the bench top
(BENCH_RECT_CFG["work_heights_m"]), the largest axis-aligned rectangle on the bench top, in the base frame facing the bench, where the hand can work, shrunk by BENCH_RECT_CFG["margin_m"].
Both arms united (either arm), and each arm alone for comparison. Prints the numbers and writes a top-down picture.

    python experiments/bench_rectangle_measure.py [--out docs/reports/bench_rectangle.png]

Loads the compiled model for the robot's geometry only (no simulation step).
"""

import argparse
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import matplotlib  # noqa: E402

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402

from src.bench_rectangle import load_maps, measure_rectangle  # noqa: E402
from src.stance_finder import robot_geometry  # noqa: E402
from src.task_beaker_hotplate import bench_top_z, load_task  # noqa: E402
from src.task_config import BENCH_RECT_CFG, TASK_CFG  # noqa: E402


def main(out):
    sim = load_task(cameras=False)
    robot = robot_geometry(sim.model)
    top = bench_top_z(sim.model)
    q = TASK_CFG["pedestal_q"]
    maps = load_maps(PROJECT_ROOT / "data" / "reach_map")
    print(f"bench top {top:.3f} m, pedestal {q} m, work heights above the top {BENCH_RECT_CFG['work_heights_m']}, margin {BENCH_RECT_CFG['margin_m']} m, {len(maps)} maps")
    res = {}
    for tag, arms in (("either arm", ("left", "right")), ("left arm", ("left",)), ("right arm", ("right",))):
        m = measure_rectangle(robot, maps, q, top, arms=arms)
        res[tag] = m
        print(f"\n{tag}: raw {m['raw']}, area {m['area_m2']:.3f} m^2\n  shrunk by the margin: {m['rectangle']}")
    m = res["either arm"]
    fig, axs = plt.subplots(1, 3, figsize=(15, 5.2))
    for ax, (tag, mm) in zip(axs, res.items()):
        xs, ys = mm["xs"], mm["ys"]
        ax.imshow(mm["mask"].T, origin="lower", extent=[xs[0], xs[-1], ys[0], ys[-1]], cmap="Blues", alpha=0.6, aspect="equal")
        for z, a in mm["per_height"].items():
            ax.contour(xs, ys, a.T.astype(float), levels=[0.5], linewidths=0.7, colors="gray")
        for key, col in (("raw", "tab:orange"), ("rectangle", "tab:red")):
            r = mm[key]
            if r:
                ax.add_patch(plt.Rectangle((r["forward_near"], r["right"]), r["forward_far"] - r["forward_near"], r["left"] - r["right"], fill=False, ec=col, lw=2, label=key if key == "raw" else "shrunk (used)"))
        ax.plot([0], [0], "k+", ms=12)
        ax.set_title(f"{tag}: reachable at all work heights (blue), the largest rectangle", fontsize=9)
        ax.set_xlabel("forward from the base origin, m (the bench is ahead)")
        ax.set_ylabel("left of the base, m")
        ax.legend(loc="upper right", fontsize=8)
    fig.suptitle(f"Bench rectangle, base frame facing the bench; pedestal {q} m; the hand's pad centre {BENCH_RECT_CFG['work_heights_m']} m above the bench top", fontsize=10)
    fig.tight_layout()
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out, dpi=110)
    print(f"\npicture: {out}")
    return m["rectangle"] is not None


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=str(PROJECT_ROOT / "docs" / "reports" / "bench_rectangle.png"))
    sys.exit(0 if main(ap.parse_args().out) else 1)
